// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        address initialCEO = c.ceoAddress();

        vm.assume(caller == initialCEO);

        vm.prank(caller);
        bool ok;
        try c.DrugDealer() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == true && c.ceoAddress() == caller);
    }
}
